# Problem: #3946 Maximum Number of Items From Sale I
# Language: python3
# Submission Result: Submission Sent (Check LeetCode Profile)
# Auto-generated by LeetCode Agent

class Solution:
    def maximumSaleItems(self, items: List[List[int]], budget: int) -> int:
        factor_list, price_list = zip(*items)
        min_price = min(price_list)
        max_sales_dp = [total_cash // min_price for total_cash in range(budget + 1)]
        
        for item_factor, item_price in items:
            bonus_gain = sum(other_factor % item_factor == 0 for other_factor in factor_list)
            for current_budget in range(budget, item_price - 1, -1):
                max_sales_dp[current_budget] = max(
                    max_sales_dp[current_budget],
                    max_sales_dp[current_budget - item_price] + bonus_gain
                )
                
        return max_sales_dp[budget]